mapper.select:
SELECT i.*,
       d.flow_code,
        AS business_title
FROM flow_instance i
LEFT JOIN flow_definition d ON d.id = i.definition_id
WHERE i.del_flag = '0'
AND i.create_by = #{createBy}
AND EXISTS (
    SELECT 1 FROM flow_definition d WHERE d.id = i.definition_id AND d.flow_code = #{flowCode}
)
AND i.flow_name LIKE CONCAT('%', #{flowName}, '%')
AND i.business_id = #{businessId}
AND i.flow_status = #{flowStatus}
AND i.create_time >= #{timeStart}
AND i.create_time < concat(#{timeEnd}, ' 23:59:59')
ORDER BY i.create_time DESC
